import { spawn } from "node:child_process";
import fs from "node:fs";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { evaluateStop, findReplayTags, GUARD_LOOKUP_TIMEOUT_MS, GUARD_MAX_BLOCKS, GUARD_MAX_MINUTES, guardStop, nextGuardState, recordReplayLaunches, stopHookOutput, trackedFromLaunches, } from "./replayStopGuard.js";
const WAIT = "/plugin/dist/commands/waitForExperiment.js";
const MINUTE = 60 * 1000;
function deps(byTag, nowMs = 0) {
    const limits = [];
    return {
        limits,
        listTagged: async (tag, limit) => {
            limits.push(limit);
            const found = byTag[tag.value];
            if (found instanceof Error) {
                throw found;
            }
            return found ?? [];
        },
        nowMs: () => nowMs,
    };
}
function tracked(overrides = {}) {
    return { tag: "batch-1", replays: 1, firstSeenMs: 0, blocks: 0, ...overrides };
}
describe("findReplayTags", () => {
    it("finds one tag per tagged bitfab-replay launch in the command", () => {
        const command = [
            "bitfab-replay --registry r.py --metadata bitfab-wait=batch-1 > a.log 2>&1 &",
            "bitfab-replay --registry r.py --metadata=bitfab-wait=batch-1 --cloud --cloud-detach",
            "bitfab-replay --registry r.py --metadata 'bitfab-wait=batch-2'",
        ].join("\n");
        expect(findReplayTags({ command })).toEqual([
            "batch-1",
            "batch-1",
            "batch-2",
        ]);
    });
    it("reads a command given as an argument list", () => {
        expect(findReplayTags({
            command: ["bitfab-replay", "--metadata", "bitfab-wait=batch-1"],
        })).toEqual(["batch-1"]);
    });
    it("skips untagged launches, resumed runs, and text outside the command", () => {
        expect(findReplayTags({ command: "bitfab-replay --registry r.py" })).toEqual([]);
        expect(findReplayTags({
            command: "bitfab-replay --resume abc --metadata bitfab-wait=batch-1 --registry r.py",
        })).toEqual([]);
        expect(findReplayTags({
            content: "bitfab-replay --metadata bitfab-wait=batch-1",
        })).toEqual([]);
    });
});
describe("trackedFromLaunches", () => {
    const launches = [
        { tag: "batch-1", atMs: 100 },
        { tag: "batch-2", atMs: 200 },
        { tag: "batch-1", atMs: 300 },
    ];
    it("counts each launch against its tag and keeps the first time it was seen", () => {
        expect(trackedFromLaunches(launches, {})).toEqual([
            { tag: "batch-1", replays: 2, firstSeenMs: 100, blocks: 0 },
            { tag: "batch-2", replays: 1, firstSeenMs: 200, blocks: 0 },
        ]);
    });
    it("skips tags whose launches were all cleared, and tracks a cleared tag again after a new launch", () => {
        const cleared = { "batch-1": { blocks: 0, clearedLaunches: 2 } };
        expect(trackedFromLaunches(launches, cleared)).toEqual([
            { tag: "batch-2", replays: 1, firstSeenMs: 200, blocks: 0 },
        ]);
        expect(trackedFromLaunches([...launches, { tag: "batch-1", atMs: 900 }], cleared)[0]).toEqual({ tag: "batch-1", replays: 3, firstSeenMs: 900, blocks: 0 });
    });
    it("carries the refusal count kept for a tag", () => {
        expect(trackedFromLaunches(launches, {
            "batch-2": { blocks: 3, clearedLaunches: 0 },
        })[1].blocks).toBe(3);
    });
});
describe("nextGuardState", () => {
    it("keeps the refusal count of tags still running and clears the launches of the rest", () => {
        const launches = [
            { tag: "batch-1", atMs: 0 },
            { tag: "batch-1", atMs: 0 },
            { tag: "batch-2", atMs: 0 },
        ];
        const tracked = trackedFromLaunches(launches, {});
        expect(nextGuardState({}, launches, tracked, [{ ...tracked[1], blocks: 1 }])).toEqual({
            "batch-1": { blocks: 0, clearedLaunches: 2 },
            "batch-2": { blocks: 1, clearedLaunches: 0 },
        });
    });
});
describe("evaluateStop", () => {
    it("blocks while a tagged experiment is pending and names the foreground wait", async () => {
        const result = await evaluateStop([tracked({ replays: 2 })], WAIT, deps({
            "batch-1": [
                { experimentId: "a", status: "pending" },
                { experimentId: "b", status: "completed" },
            ],
        }));
        expect(result.message).toContain("1 Bitfab replay(s) you started");
        expect(result.message).toContain("Do not end your turn");
        expect(result.message).toContain(`node ${WAIT} --metadata bitfab-wait=batch-1 --count 2`);
        expect(result.message).toContain("never the background");
        expect(result.remaining).toEqual([tracked({ replays: 2, blocks: 1 })]);
    });
    it("counts launched replays whose experiments have not appeared yet", async () => {
        const result = await evaluateStop([tracked({ replays: 3 })], WAIT, deps({ "batch-1": [{ experimentId: "a", status: "completed" }] }));
        expect(result.message).toContain("2 Bitfab replay(s)");
    });
    it("lets the turn end and forgets the tag once every experiment finished", async () => {
        const lookups = deps({
            "batch-1": [
                { experimentId: "a", status: "completed" },
                { experimentId: "b", status: "failed" },
            ],
        });
        const result = await evaluateStop([tracked({ replays: 2 })], WAIT, lookups);
        expect(result).toEqual({ message: null, remaining: [] });
        expect(lookups.limits).toEqual([2]);
    });
    it("stops blocking after the time limit or the block limit", async () => {
        const pending = { "batch-1": [{ experimentId: "a", status: "pending" }] };
        const late = await evaluateStop([tracked()], WAIT, deps(pending, (GUARD_MAX_MINUTES + 1) * MINUTE));
        const blockedOften = await evaluateStop([tracked({ blocks: GUARD_MAX_BLOCKS })], WAIT, deps(pending));
        expect(late).toEqual({ message: null, remaining: [] });
        expect(blockedOften).toEqual({ message: null, remaining: [] });
    });
    it("does not block when the lookup fails, but keeps the tag for the next stop", async () => {
        const result = await evaluateStop([tracked()], WAIT, deps({ "batch-1": new Error("offline") }));
        expect(result).toEqual({ message: null, remaining: [tracked()] });
    });
});
describe("stopHookOutput", () => {
    it("blocks the stop in Claude Code and Codex, and sends a follow-up in Cursor", () => {
        expect(stopHookOutput("claude-code", "wait")).toEqual({
            decision: "block",
            reason: "wait",
        });
        expect(stopHookOutput("codex", "wait")).toEqual({
            decision: "block",
            reason: "wait",
        });
        expect(stopHookOutput("cursor", "wait")).toEqual({
            followup_message: "wait",
        });
    });
});
describe("guardStop against a Bitfab server", () => {
    const SESSION = "guard-session";
    let home;
    let server;
    let respond;
    const requests = [];
    function stateFile() {
        return path.join(home, ".config", "bitfab", "sessions", `${SESSION}.replay-waits.json`);
    }
    function experiments(statuses) {
        return (res) => {
            res.setHeader("content-type", "application/json");
            res.end(JSON.stringify({
                experiments: statuses.map((status, i) => ({ id: `e${i}`, status })),
            }));
        };
    }
    beforeEach(async () => {
        home = fs.mkdtempSync(path.join(os.tmpdir(), "bitfab-guard-"));
        requests.length = 0;
        server = http.createServer((req, res) => {
            requests.push(`${req.headers.authorization} ${req.url}`);
            respond(res);
        });
        await new Promise((resolve) => server.listen(0, resolve));
        const { port } = server.address();
        vi.stubEnv("HOME", home);
        vi.stubEnv("BITFAB_SERVICE_URL", `http://127.0.0.1:${port}`);
        vi.stubEnv("BITFAB_API_KEY", "test-key");
        recordReplayLaunches(SESSION, {
            command: "bitfab-replay --metadata bitfab-wait=batch-1 & bitfab-replay --metadata bitfab-wait=batch-1",
        });
    });
    afterEach(async () => {
        vi.unstubAllEnvs();
        server.closeAllConnections();
        await new Promise((resolve) => server.close(() => resolve()));
        fs.rmSync(home, { recursive: true, force: true });
    });
    it("refuses the stop while a tagged experiment is pending, asking the server with the tag", async () => {
        respond = experiments(["pending", "completed"]);
        const output = await guardStop(SESSION, "claude-code", undefined);
        expect(output?.decision).toBe("block");
        expect(output?.reason).toContain("--metadata bitfab-wait=batch-1 --count 2");
        expect(decodeURIComponent(requests[0])).toContain('Bearer test-key /api/sdk/experiments?metadata={"bitfab-wait":"batch-1"}&limit=2');
        expect(JSON.parse(fs.readFileSync(stateFile(), "utf-8"))).toEqual({
            "batch-1": { blocks: 1, clearedLaunches: 0 },
        });
    });
    it("lets the turn end and clears the session once every experiment finished", async () => {
        respond = experiments(["completed", "failed"]);
        expect(await guardStop(SESSION, "cursor", undefined)).toBeNull();
        expect(await guardStop(SESSION, "cursor", undefined)).toBeNull();
        expect(requests).toHaveLength(1);
    });
    it("lets the turn end within the lookup timeout when the server never answers", async () => {
        respond = () => undefined;
        const started = Date.now();
        const output = await guardStop(SESSION, "claude-code", undefined);
        expect(output).toBeNull();
        expect(Date.now() - started).toBeLessThan(GUARD_LOOKUP_TIMEOUT_MS + 2000);
        expect(JSON.parse(fs.readFileSync(stateFile(), "utf-8"))).toEqual({
            "batch-1": { blocks: 0, clearedLaunches: 0 },
        });
    }, GUARD_LOOKUP_TIMEOUT_MS + 5000);
    it("stops refusing after the block limit", async () => {
        respond = experiments(["pending"]);
        const outputs = [];
        for (let i = 0; i <= GUARD_MAX_BLOCKS; i++) {
            outputs.push(await guardStop(SESSION, "codex", undefined));
        }
        expect(outputs.slice(0, GUARD_MAX_BLOCKS).every((o) => o !== null)).toBe(true);
        expect(outputs[GUARD_MAX_BLOCKS]).toBeNull();
        expect(await guardStop(SESSION, "codex", undefined)).toBeNull();
        expect(requests).toHaveLength(GUARD_MAX_BLOCKS);
    });
    it("keeps every launch when several hooks record them at the same time", async () => {
        respond = experiments(Array(10).fill("pending"));
        const guardModule = path.join(import.meta.dirname, "replayStopGuard.ts");
        const record = `import(${JSON.stringify(guardModule)}).then((m) => m.recordReplayLaunches(${JSON.stringify(SESSION)}, { command: "bitfab-replay --metadata bitfab-wait=batch-1" }))`;
        const writers = Array.from({ length: 8 }, () => spawn(process.execPath, ["--import", "tsx", "--eval", record], {
            env: { ...process.env, HOME: home },
            stdio: "ignore",
        }));
        await Promise.all(writers.map((writer) => new Promise((resolve) => writer.on("exit", () => resolve()))));
        const output = await guardStop(SESSION, "claude-code", undefined);
        expect(output?.reason).toContain("--count 10");
        expect(decodeURIComponent(requests[0])).toContain("&limit=10");
    }, 30_000);
});
